CommandPhase.start:
start() {
    super.start();

    if (this.fieldIndex) {
      const allyCommand = this.scene.currentBattle.turnCommands[this.fieldIndex - 1];
      if (allyCommand.command === Command.BALL || allyCommand.command === Command.RUN)
        this.scene.currentBattle.turnCommands[this.fieldIndex] = { command: allyCommand.command, skip: true };
    }

    if (this.scene.currentBattle.turnCommands[this.fieldIndex]?.skip)
      return this.end();

    const playerPokemon = this.scene.getPlayerField()[this.fieldIndex];

    const forced = prepareQueuedFight(playerPokemon);
    if (forced)
      this.handleCommand(Command.FIGHT, forced.cursor, ...forced.args);
    else
      this.scene.ui.setMode(Mode.COMMAND, this.fieldIndex);
  }

CommandPhase.handleCommand:
handleCommand(command: Command, cursor: integer, ...args: any[]): boolean {
    const playerPokemon = this.scene.getPlayerField()[this.fieldIndex];
    const enemyField = this.scene.getEnemyField();
    let success: boolean;

    switch (command) {
      case Command.FIGHT:
        const selection = selectFightCommand(playerPokemon, this.fieldIndex, cursor, args, {
          fightCommand: Command.FIGHT, noneMove: Moves.NONE, struggleMove: Moves.STRUGGLE, getMoveTargets
        });
        if (selection) {
          console.log(selection.targets, playerPokemon.name);
          if (selection.needsTarget)
            this.scene.unshiftPhase(new SelectTargetPhase(this.scene, this.fieldIndex));
          this.scene.currentBattle.turnCommands[this.fieldIndex] = selection.command;
          success = true;
        } else if (cursor < playerPokemon.getMoveset().length) {
          const move = playerPokemon.getMoveset()[cursor];
          if (playerPokemon.summonData.disabledMove === move.moveId) {
            this.scene.ui.setMode(Mode.MESSAGE);
            this.scene.ui.showText(i18next.t("battle:moveDisabled", { moveName: (move.getName()) }), null, () => {
              this.scene.ui.clearText();
              this.scene.ui.setMode(Mode.FIGHT, this.fieldIndex);
            }, null, true);
          }
        }
        break;
      case Command.BALL:
        if (this.scene.arena.biomeType === Biome.END) {
          this.scene.ui.setMode(Mode.COMMAND, this.fieldIndex);
          this.scene.ui.setMode(Mode.MESSAGE);
          this.scene.ui.showText(`An unseen force\nprevents using Poké Balls.`, null, () => {
            this.scene.ui.showText(null, 0);
            this.scene.ui.setMode(Mode.COMMAND, this.fieldIndex);
          }, null, true);
        } else if (this.scene.currentBattle.battleType === BattleType.TRAINER) {
          this.scene.ui.setMode(Mode.COMMAND, this.fieldIndex);
          this.scene.ui.setMode(Mode.MESSAGE);
          this.scene.ui.showText(i18next.t("battle:noPokeballTrainer"), null, () => {
            this.scene.ui.showText(null, 0);
            this.scene.ui.setMode(Mode.COMMAND, this.fieldIndex);
          }, null, true);
        } else {
          const targets = this.scene.getEnemyField().filter(p => p.isActive(true)).map(p => p.getBattlerIndex());
          if (targets.length > 1) {
            this.scene.ui.setMode(Mode.COMMAND, this.fieldIndex);
            this.scene.ui.setMode(Mode.MESSAGE);
            this.scene.ui.showText(i18next.t("battle:noPokeballMulti"), null, () => {
              this.scene.ui.showText(null, 0);
              this.scene.ui.setMode(Mode.COMMAND, this.fieldIndex);
            }, null, true);
          } else if (cursor < 5) {
            const targetPokemon = this.scene.getEnemyField().find(p => p.isActive(true));
            if (targetPokemon.isBoss() && targetPokemon.bossSegmentIndex >= 1) {
              this.scene.ui.setMode(Mode.COMMAND, this.fieldIndex);
              this.scene.ui.setMode(Mode.MESSAGE);
              this.scene.ui.showText(i18next.t("battle:noPokeballStrong"), null, () => {
                this.scene.ui.showText(null, 0);
                this.scene.ui.setMode(Mode.COMMAND, this.fieldIndex);
              }, null, true);
            } else {
              this.scene.currentBattle.turnCommands[this.fieldIndex] = { command: Command.BALL, cursor: cursor };
              this.scene.currentBattle.turnCommands[this.fieldIndex].targets = targets;
              if (this.fieldIndex)
                this.scene.currentBattle.turnCommands[this.fieldIndex - 1].skip = true;
              success = true;
            }
          }
        }
        break;
      case Command.POKEMON:
      case Command.RUN:
        const isSwitch = command === Command.POKEMON;
        if (!isSwitch && this.scene.arena.biomeType === Biome.END) {
          this.scene.ui.setMode(Mode.COMMAND, this.fieldIndex);
          this.scene.ui.setMode(Mode.MESSAGE);
          this.scene.ui.showText(i18next.t("battle:noEscapeForce"), null, () => {
            this.scene.ui.showText(null, 0);
            this.scene.ui.setMode(Mode.COMMAND, this.fieldIndex);
          }, null, true);
        } else if (!isSwitch && this.scene.currentBattle.battleType === BattleType.TRAINER) {
          this.scene.ui.setMode(Mode.COMMAND, this.fieldIndex);
          this.scene.ui.setMode(Mode.MESSAGE);
          this.scene.ui.showText(i18next.t("battle:noEscapeTrainer"), null, () => {
            this.scene.ui.showText(null, 0);
            this.scene.ui.setMode(Mode.COMMAND, this.fieldIndex);
          }, null, true);
        } else {
          const trapTag = playerPokemon.findTag(t => t instanceof TrappedTag) as TrappedTag;
          const trapped = new Utils.BooleanHolder(false);
          const batonPass = isSwitch && args[0] as boolean;
          if (!batonPass)
            enemyField.forEach(enemyPokemon => applyCheckTrappedAbAttrs(CheckTrappedAbAttr, enemyPokemon, trapped));
          if (batonPass || (!trapTag && !trapped.value)) {
            this.scene.currentBattle.turnCommands[this.fieldIndex] = isSwitch
              ? { command: Command.POKEMON, cursor: cursor, args: args }
              : { command: Command.RUN };
            success = true;
            if (!isSwitch && this.fieldIndex)
              this.scene.currentBattle.turnCommands[this.fieldIndex - 1].skip = true;
          } else if (trapTag) {
            if (!isSwitch) {
              this.scene.ui.setMode(Mode.COMMAND, this.fieldIndex);
              this.scene.ui.setMode(Mode.MESSAGE);
            }
            this.scene.ui.showText(i18next.t('battle:noEscapePokemon', {
              pokemonName: this.scene.getPokemonById(trapTag.sourceId).name,
              moveName: trapTag.getMoveName(),
              escapeVerb: i18next.t(isSwitch ? 'battle:escapeVerbSwitch' : 'battle:escapeVerbFlee')
            }), null, () => {
              this.scene.ui.showText(null, 0);
              if (!isSwitch)
                this.scene.ui.setMode(Mode.COMMAND, this.fieldIndex);
            }, null, true);
          }
        }
        break;
    }

    if (success)
      this.end();

    return success;
  }

CommandPhase.cancel:
cancel() {
    if (this.fieldIndex) {
      this.scene.unshiftPhase(new CommandPhase(this.scene, 0));
      this.scene.unshiftPhase(new CommandPhase(this.scene, 1));
      this.end();
    }
  }

CommandPhase.checkFightOverride:
checkFightOverride(): boolean {
    const forced = selectEncoreFight(this.getPokemon(), pokemon => pokemon.getTag(EncoreTag));
    if (!forced) return false;
    this.handleCommand(Command.FIGHT, forced.cursor, ...forced.args);
    return true;
  }

SelectTargetPhase.start:
start() {
    super.start();

    const turnCommand = this.scene.currentBattle.turnCommands[this.fieldIndex];
    const move = turnCommand.move?.move;
    this.scene.ui.setMode(Mode.TARGET_SELECT, this.fieldIndex, move, (cursor: integer) => {
      this.scene.ui.setMode(Mode.MESSAGE);
      applyTargetSelection(this.scene.currentBattle.turnCommands, this.fieldIndex, cursor, {
        ballCommand: Command.BALL,
        requeueCommand: index => this.scene.unshiftPhase(new CommandPhase(this.scene, index))
      }, turnCommand);
      this.end();
    });
  }

EnemyCommandPhase.start:
start() {
    super.start();
    const enemyPokemon = this.scene.getEnemyField()[this.fieldIndex];
    this.scene.currentBattle.turnCommands[this.fieldIndex + BattlerIndex.ENEMY] = selectEnemyCommand(enemyPokemon, this.scene.currentBattle.trainer, {
      batonPassMove: Moves.BATON_PASS,
      fightCommand: Command.FIGHT,
      switchCommand: Command.POKEMON,
      findTrapTag: pokemon => pokemon.findTag(t => t instanceof TrappedTag),
      isAbilityTrapped: opponents => {
        const trapped = new Utils.BooleanHolder(false);
        opponents.forEach(playerPokemon => applyCheckTrappedAbAttrs(CheckTrappedAbAttr, playerPokemon, trapped));
        return trapped.value;
      }
    });
    this.end();
  }

pokemonMethods.getNextMove:
getNextMove(): QueuedMove {
    const queuedMove = this.getMoveQueue().length
      ? this.getMoveset().find(m => m.moveId === this.getMoveQueue()[0].move)
      : null;
    if (queuedMove) {
      if (queuedMove.isUsable(this, this.getMoveQueue()[0].ignorePP))
        return { move: queuedMove.moveId, targets: this.getMoveQueue()[0].targets, ignorePP: this.getMoveQueue()[0].ignorePP };
      else {
        this.getMoveQueue().shift();
        return this.getNextMove();
      }
    }

    const movePool = this.getMoveset().filter(m => m.isUsable(this));
    if (movePool.length) {
      if (movePool.length === 1)
        return { move: movePool[0].moveId, targets: this.getNextTargets(movePool[0].moveId) };
      const encoreTag = this.getTag(EncoreTag) as EncoreTag;
      if (encoreTag) {
        const encoreMove = movePool.find(m => m.moveId === encoreTag.moveId);
        if (encoreMove)
          return { move: encoreMove.moveId, targets: this.getNextTargets(encoreMove.moveId) };
      }
      switch (this.aiType) {
        case AiType.RANDOM:
          const moveId = movePool[this.scene.currentBattle.randSeedInt(movePool.length)].moveId;
          return { move: moveId, targets: this.getNextTargets(moveId) };
        case AiType.SMART_RANDOM:
        case AiType.SMART:
          const moveScores = movePool.map(() => 0);
          const moveTargets = Object.fromEntries(movePool.map(m => [ m.moveId, this.getNextTargets(m.moveId) ]));
          for (let m in movePool) {
            const pokemonMove = movePool[m];
            const move = pokemonMove.getMove();
            let moveScore = moveScores[m];

            let targetScores: integer[] = [];

            for (let mt of moveTargets[move.id]) {
              const target = this.scene.getField()[mt];
              let targetScore = move.getUserBenefitScore(this, target, move) + move.getTargetBenefitScore(this, target, move) * (mt < BattlerIndex.ENEMY === this.isPlayer() ? 1 : -1);
              if (move instanceof AttackMove) {
                const effectiveness = target.getAttackMoveEffectiveness(this, pokemonMove);
                if (target.isPlayer() !== this.isPlayer()) {
                  targetScore *= effectiveness;
                  if (this.isOfType(move.type))
                    targetScore *= 1.5;
                } else {
                  targetScore /= effectiveness;
                  if (this.isOfType(move.type))
                    targetScore /= 1.5;
                }
              }
              targetScores.push(targetScore);
            }

            moveScore += Math.max(...targetScores);

            // could make smarter by checking opponent def/spdef
            moveScores[m] = moveScore;
          }

          console.log(moveScores);

          const sortedMovePool = movePool.slice(0);
          sortedMovePool.sort((a, b) => {
            const scoreA = moveScores[movePool.indexOf(a)];
            const scoreB = moveScores[movePool.indexOf(b)];
            return scoreA < scoreB ? 1 : scoreA > scoreB ? -1 : 0;
          });
          let r = 0;
          if (this.aiType === AiType.SMART_RANDOM) {
            while (r < sortedMovePool.length - 1 && this.scene.currentBattle.randSeedInt(8) >= 5)
              r++;
          }
          console.log(movePool.map(m => m.getName()), moveScores, r, sortedMovePool.map(m => m.getName()));
          return { move: sortedMovePool[r].moveId, targets: moveTargets[sortedMovePool[r].moveId] };
      }
    }

    return { move: Moves.STRUGGLE, targets: this.getNextTargets(Moves.STRUGGLE) };
  }

pokemonMethods.getNextTargets:
getNextTargets(moveId: Moves): BattlerIndex[] {
    const moveTargets = getMoveTargets(this, moveId);
    const targets = this.scene.getField(true).filter(p => moveTargets.targets.indexOf(p.getBattlerIndex()) > -1);
    if (moveTargets.multiple)
      return targets.map(p => p.getBattlerIndex());

    const move = allMoves[moveId];

    const benefitScores = targets
      .map(p => [ p.getBattlerIndex(), move.getTargetBenefitScore(this, p, move) * (p.isPlayer() === this.isPlayer() ? 1 : -1) ]);

    const sortedBenefitScores = benefitScores.slice(0);
    sortedBenefitScores.sort((a, b) => {
      const scoreA = a[1];
      const scoreB = b[1];
      return scoreA < scoreB ? 1 : scoreA > scoreB ? -1 : 0;
    });

    if (!sortedBenefitScores.length)
      return [];

    let targetWeights = sortedBenefitScores.map(s => s[1]);
    const lowestWeight = targetWeights[targetWeights.length - 1];

    if (lowestWeight < 1) {
      for (let w = 0; w < targetWeights.length; w++)
        targetWeights[w] += Math.abs(lowestWeight - 1);
    }

    const benefitCutoffIndex = targetWeights.findIndex(s => s < targetWeights[0] / 2);
    if (benefitCutoffIndex > -1)
      targetWeights = targetWeights.slice(0, benefitCutoffIndex);

    const thresholds: integer[] = [];
    let totalWeight: integer;
    targetWeights.reduce((total: integer, w: integer) => {
      total += w;
      thresholds.push(total);
      totalWeight = total;
      return total;
    }, 0);

    const randValue = this.scene.currentBattle.randSeedInt(totalWeight);
    let targetIndex: integer;

    thresholds.every((t, i) => {
      if (randValue >= t)
        return true;

      targetIndex = i;
      return false;
    });

    return [ sortedBenefitScores[targetIndex][0] ];
  }
